"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1010-08-15:0":{"b": ["Valencia (Belensije) ra në duart e liberteve amiride Mubarek dhe Muzaffer", "38ac8e22"], "d": ["Me shpërbërjen e pushtetit të nipërve të Haxhib Mansurit, Valencia hyri nën administrimin e liberteve të amiridëve, Mubarekut dhe Muzafferit; në Andaluzi nisën të shfaqen emiratet taifa.", "82f013cc"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1013-01-01:0":{"b": ["Sulejman el-Mustaini dhe përkrahësit e tij hynë në Kordovë dhe e rrëzuan sërish Hishamin II nga froni; në qytet u vranë të paktën gjashtëdhjetë dijetarë (403/1013; burimi jep vitin, dita mungon).", "e863c0b4"], "d": ["Sulejman el-Mustaini dhe përkrahësit e tij hynë në Kordovë dhe e rrëzuan sërish Hishamin II nga froni; në qytet u vranë të paktën gjashtëdhjetë dijetarë (403/1013; burimi jep vitin, dita mungon).", "e863c0b4"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1016-01-01:0":{"b": ["Hamudidët pushtuan Kordovën dhe fronin e Andaluzisë", "a8a8ea65"], "d": ["Hamudidët shiitë, që pretendonin se vinin nga gjaku alevit, duke përfituar nga pafuqia e dinastisë umajade, në 1016 vunë dorë mbi Kordovën dhe fronin e halifatit; Kordova mbeti nën sundimin e tyre midis viteve 1016-1022.", "b088ab2a"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1021-01-01:0":{"b": ["Dinastia amiride u themelua me qendër në Valencia (1021-1094)", "ebf0b6e2"], "d": ["Abdulaziz b. Abdurrahmani, nip i haxhib el-Mansurit, në 1021 themeloi emiratin taifa amirid me qendër në Valencia; dinastia vazhdoi, me disa ndërprerje, deri në 1094.", "dc1ccee5"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1023-03-26:0":{"b": ["Kadiu Ibn Abad e shpalli Seviljen qendër të qeverisjes (abadidët)", "931db55e"], "d": ["Kadiu Ebu'l-Kasim Ibn Abad në vitin 414 (1023) e shpalli Seviljen qendër të qeverisjes; emirati taifa abadid u shndërrua në një nga qendrat më të rëndësishme të Andaluzisë.", "51e3b6d5"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1031-01-01:0":{"b": ["Kordova u bë republikë nën administrimin e xhevheritëve (1031-1070)", "943bc77c"], "d": ["Pas shuarjes së dinastisë umajade, Kordova nga 1031 deri në 1070 u shndërrua në republikë nën administrimin e xhevheritëve.", "6afd1a28"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1049-06-05:0":{"b": ["Kur veziri fatimid el-Jazuri e emëroi kryetarin e Zugbes emir të Tripolit dhe Gabesit, Beni Hilali u drejtua drejt perëndimit (441, 1049).", "481a1144"], "d": ["Kur veziri fatimid el-Jazuri e emëroi kryetarin e Zugbes emir të Tripolit dhe Gabesit, Beni Hilali u drejtua drejt perëndimit (441, 1049).", "481a1144"]},
