"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0834-01-01:0":{"b": ["Abdullah b. Tahiri shtypi Muhamed b. Kasimin që u ngrit në kryengritje në Talekan.", "00591821"], "d": ["Abdullah b. Tahiri shtypi Muhamed b. Kasimin që u ngrit në kryengritje në Talekan.", "00591821"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0844-01-01:0":{"b": ["Abdullah b. Tahiri vdiq; e pasoi i biri Tahiri II", "d2235609"], "d": ["Abdullah b. Tahiri vdiq; e pasoi i biri Tahiri II", "d2235609"]},
