"OLAYLAR_ORTACAG_ORTADOGU:0705-01-02:0":{"b": ["Velidi I u bë kalif (86/705); në kohën e tij Shteti Umajad arriti kufijtë më të gjerë.", "c848f25f"], "d": ["Velidi I u bë kalif (86/705); në kohën e tij Shteti Umajad arriti kufijtë më të gjerë.", "c848f25f"]},
"OLAYLAR_ORTACAG_ORTADOGU:0711-07-26:0":{"b": ["Tarik b. Zijadi i shkaktoi një disfatë të rëndë ushtrisë vizigote", "73301b6a"], "d": ["Në fund të betejës tetëditore midis dy ushtrive, ushtria vizigote pësoi një disfatë të rëndë (5 sheval 92 / 26 korrik 711); vendi i betejës është bregu i Guadalete-s ose Barbate-s. Tregohet se Tariku për një kohë të shkurtër pushtoi Malagën, Elvirën, Kordobën dhe Toledon.", "12d78ad9"]},
"OLAYLAR_ORTACAG_ORTADOGU:0712-06-20:0":{"b": ["Përballë Muhamed b. Kasimit vdiq raxha i Sindit Dahiri; u pushtuan Ruri (Arur, Aror), Brahmanabadi dhe Multani", "bccf3c4f"], "d": ["Sundimtari i Sindit Dahiri, që luftonte me komandantin umajad Muhamed b. Kasim, vdiq më 10 ramazan 93 / 20 qershor 712; pas kësaj beteje u pushtuan Ruri (Arur, Aror), Brahmanabadi dhe Multani dhe i gjithë Sindi kaloi në duart e Umajadëve.", "e213eabd"]},
"OLAYLAR_ORTACAG_ORTADOGU:0724-01-01:0":{"b": ["Hisham b. Abdulmeliku u bë kalif (105/724); sundoi deri në 743.", "6288b8a9"], "d": ["Hisham b. Abdulmeliku u bë kalif (105/724); sundoi deri në 743.", "6288b8a9"]},
